var game: Node = get_tree().current_scene
var old: Array = []
for name: String in ["Ground","LeftPlatform","RightPlatform","TopPlatform"]:
	var body: Node = game.get_node("Arena/"+name)
	old.append({"id":name,"layer":body.collision_layer,"disabled":body.get_node("CollisionShape2D").disabled})
var regions: Array = []
for id: StringName in game.get_node("DynamicGeometry").object_ids():
	var body: Node = game.get_node("DynamicGeometry").get_body(id)
	regions.append({"id":id,"owner":body.structure_id,"material":body.material_kind,"shapes":body.colliders.size()})
return {"scene":game.scene_file_path,"state":game.get_node("SceneSource").scene_state,"applied_state":game.get_node("SceneSource").applied_state,"floor_enabled":game.get_node("SafetyFloor").enabled,"floor_reason":game.get_node("SafetyFloor").last_reason,"old":old,"regions":regions,"source":game.get_node("Replay").get_status(),"selected":[game.selected_characters[0].display_name,game.selected_characters[1].display_name],"stocks":[game.players[0].combat.damage_model.stocks,game.players[1].combat.damage_model.stocks],"no_udp":game.get_node_or_null("ExternalPlatformReceiver")==null and game.get_node_or_null("StructureUdpReceiver")==null}
